### Option (a): Employee Salary Calculation by Gender & Years of Service

**C Program:**
```c
#include <stdio.h>
int main()
{
    int years_of_service;
    char gender;
    printf("Enter Gender (M for Male, F for Female): ");
    scanf(" %c", &gender);
    printf("Enter Years of Service: ");
    scanf("%d", &years_of_service);

    if ((gender == 'M' || gender == 'm') && (years_of_service >= 5))
        printf("Your salary is 150000");
    else if ((gender == 'M' || gender == 'm') && (years_of_service < 5))
        printf("Your salary is 100000");
    else if ((gender == 'F' || gender == 'f') && (years_of_service >= 5))
        printf("Your salary is 200000");
    else if ((gender == 'F' || gender == 'f') && (years_of_service < 5))
        printf("Your salary is 150000");
    else
        printf("Invalid input");

    return 0;
}
```

